# -*- coding: utf-8 -*-
# (speaker, french, korean); speaker None => stage direction (not a turn)
H, J, C, R = "Hélène", "Julien", "Chloé", "Étienne Roux"
D = [
(None, "Vendredi 16 octobre, 12 h 40. Le service de midi bat son plein. Julien installe un homme seul d'une soixantaine d'années, écharpe grise et carnet noir, à la table quatre.", "10월 16일 금요일 낮 12시 40분. 점심 영업이 한창이다. 쥘리앵은 회색 목도리에 검은 수첩을 든, 예순쯤 된 혼자 온 남자를 4번 테이블에 안내한다."),
(J, "Chloé, viens une seconde. Table quatre, le monsieur à l'écharpe. Tu le reconnais pas ?", "클로에, 잠깐만. 4번 테이블, 목도리 두른 저 손님. 누군지 모르겠어?"),
(C, "Non. Un client qui voyage seul ? Il a l'air sérieux.", "아니요. 혼자 오신 손님이요? 진지해 보이시네요."),
(J, "C'est Étienne Roux. Le critique du journal. Il est déjà venu il y a trois ans.", "에티엔 루야. 신문 비평가. 3년 전에 한 번 왔었어."),
(C, "Le Roux qui a écrit « une maison sincère, mais une cuisine qui a peur » ?", "« 진심 있는 가게지만 겁먹은 요리 »라고 썼던 그 루 씨요?"),
(J, "Lui-même. Ça fait trois ans qu'Hélène connaît la phrase par cœur.", "바로 그 사람. 엘렌은 3년째 그 문장을 외우고 있어."),
(C, "Mince. Je préviens Hélène ?", "이런. 엘렌한테 알릴까요?"),
(J, "Non, c'est moi. Toi, tu souris et tu ne renverses rien. Même pas une goutte d'eau.", "아니, 내가 갈게. 넌 웃고 아무것도 엎지르지 마. 물 한 방울도."),
(None, "Dans la cuisine, Hélène nappe deux assiettes. Julien entre, baisse la voix.", "주방에서 엘렌이 접시 두 개에 소스를 입히고 있다. 쥘리앵이 들어와 목소리를 낮춘다."),
(J, "Hélène, ne te retourne pas. Étienne Roux est en salle. Table quatre.", "엘렌, 돌아보지 마. 에티엔 루가 홀에 있어. 4번 테이블."),
(H, "Quoi ? Putain. Pas aujourd'hui. Pas avec Karim parti et Moussa seul à la plonge.", "뭐? 젠장. 하필 오늘이야? 카림도 없고 무사 혼자 설거지하는데."),
(J, "Il a commandé la formule à vingt-quatre euros. L'œuf mayonnaise, la blanquette, la tarte Tatin.", "24유로짜리 포뮬을 시켰어. 에그 마요네즈, 블랑케트, 타르트 타탱."),
(H, "La blanquette. Ma blanquette. Évidemment qu'il prend la blanquette de maman.", "블랑케트라고. 내 블랑케트. 당연히 엄마의 블랑케트를 시켰겠지."),
(J, "Respire. On fait comme d'habitude. On ne change rien.", "숨 쉬어. 평소처럼 하자. 아무것도 바꾸지 말고."),
(H, "On ne change rien ? Il m'a descendue en flammes il y a trois ans, tu t'en souviens ?", "아무것도 바꾸지 말라고? 3년 전에 날 아주 박살 냈잖아, 기억 안 나?"),
(J, "Je m'en souviens. Et on a survécu. Allez, l'œuf part dans deux minutes.", "기억나지. 그래도 우린 살아남았어. 자, 달걀 요리는 이 분 뒤에 나간다."),
(H, "Bordel. Bon. Moussa, la mayonnaise ! Vite !", "빌어먹을. 좋아. 무사, 마요네즈! 빨리!"),
(None, "En salle, Julien dépose le verre de Brouilly devant le critique avec un sourire parfait.", "홀에서 쥘리앵이 완벽한 미소와 함께 비평가 앞에 브루이 와인 한 잔을 놓는다."),
(R, "Merci, jeune homme. Vous m'avez reconnu, je suppose.", "고맙소, 젊은이. 날 알아본 모양이군."),
(J, "Votre photo est dans le journal, monsieur Roux. Vous êtes le bienvenu.", "신문에 사진이 실리시잖아요, 루 선생님. 환영합니다."),
(R, "Je préférerais qu'on ne le dise pas à toute la salle. Je viens manger, pas assister à un spectacle.", "홀 전체에 알리지는 않았으면 하오. 연극을 보러 온 게 아니라 밥을 먹으러 왔으니."),
(J, "Soyez tranquille. Personne ne le saura, sauf la cuisine.", "걱정 마세요. 주방 말고는 아무도 모를 겁니다."),
(R, "Ah, la cuisine le sait déjà. Évidemment. Eh bien, tant pis.", "아, 주방은 벌써 알겠군. 당연하지. 뭐, 어쩔 수 없지."),
(None, "Chloé apporte l'œuf mayonnaise. Ses mains tremblent un peu.", "클로에가 에그 마요네즈를 가져온다. 손이 조금 떨린다."),
(C, "Voici l'œuf mayonnaise, monsieur. Bon appétit.", "에그 마요네즈입니다, 손님. 맛있게 드세요."),
(R, "Merci, mademoiselle. Vous êtes nouvelle ? Je ne vous ai jamais vue.", "고맙소, 아가씨. 새로 왔나? 처음 보는데."),
(C, "Depuis avril. Je suis en alternance. Je suis aussi cuisinière, en fait.", "4월부터요. 견습생이에요. 사실 요리도 해요."),
(R, "Intéressant. Et la patronne, elle vous apprend quoi, d'abord ?", "흥미롭군. 그래, 사장은 처음에 뭘 가르쳐 주나?"),
(C, "À goûter avant d'envoyer. Toujours. Même quand il y a vingt tickets.", "내보내기 전에 꼭 맛을 보는 거요. 티켓이 스무 장이 쌓여도 항상요."),
(R, "Voilà une règle que beaucoup de brigades oublient.", "많은 주방이 잊어버리는 규칙이군."),
(None, "Il goûte l'œuf, note quelque chose, goûte à nouveau. Chloé reste plantée à côté de la table.", "그는 달걀을 맛보고 무언가 적고 다시 맛본다. 클로에는 테이블 옆에 멍하니 서 있다."),
(C, "Ça vous plaît ?", "마음에 드세요?"),
(R, "Mademoiselle, on ne pose pas cette question à un critique qui mâche.", "아가씨, 씹고 있는 비평가에게 그런 걸 묻는 게 아니오."),
(C, "Pardon, monsieur. Je m'en vais. Je m'en vais tout de suite.", "죄송합니다. 물러가겠습니다. 바로 가겠습니다."),
(R, "Attendez. Dites à la cuisinière que le jaune est coulant à point. Six minutes trente, je dirais.", "잠깐. 요리사에게 노른자가 딱 알맞게 흐른다고 전하시오. 6분 30초쯤 삶은 것 같군."),
(C, "Six minutes trente exactement ! Comment vous le savez ?", "정확히 6분 30초예요! 어떻게 아세요?"),
(R, "Quarante ans de métier. Allez, filez.", "이 일을 사십 년 했소. 자, 가 보시오."),
(None, "Dans la cuisine, Chloé arrive en courant, le visage rouge.", "주방으로 클로에가 얼굴이 빨개져서 뛰어 들어온다."),
(C, "Hélène ! Il a dit que le jaune était coulant à point. Six minutes trente !", "엘렌! 노른자가 딱 알맞게 흐른다고 했어요. 6분 30초래요!"),
(H, "Il a dit ça ? Lui ? Bon. Ne te réjouis pas. Il n'a pas encore goûté la blanquette.", "그 사람이 그랬어? 흠. 좋아하지 마. 아직 블랑케트는 먹지도 않았어."),
(C, "Elle est prête, ma blanquette ?", "블랑케트는 준비됐어요?"),
(H, "Elle est dans la casserole depuis neuf heures ce matin. La sonde indique soixante-huit degrés. Je ne sais pas.", "오늘 아침 아홉 시부터 냄비에 있어. 탐침 온도계는 68도야. 잘 모르겠네."),
(J, "Fais-moi confiance. Elle est bonne. Envoie.", "나를 믿어. 맛있어. 내보내."),
(H, "Si le veau est sec, c'est toi qui t'excuses auprès de lui.", "송아지가 퍽퍽하면 그 사람한테 네가 사과하는 거야."),
(J, "Marché conclu. Je suis très bon pour m'excuser.", "좋아, 합의야. 난 사과를 아주 잘하거든."),
(H, "Je n'ai pas le choix, de toute façon. Allez, Chloé. Prends les deux assiettes. Doucement.", "어차피 선택지가 없지. 자, 클로에. 접시 두 개 들어. 살살."),
(None, "Quelques minutes plus tard, Julien débarrasse l'entrée. Le critique mange la blanquette en silence, puis lève la tête.", "몇 분 뒤 쥘리앵이 앞 접시를 치운다. 비평가는 말없이 블랑케트를 먹다가 고개를 든다."),
(R, "Monsieur, voudriez-vous demander à la patronne de passer me voir, quand elle aura un instant ?", "선생, 사장님께 잠깐 시간 나실 때 와 달라고 전해 주시겠소?"),
(J, "Bien sûr. J'y vais. Vous voulez un peu de vin avant ?", "물론입니다. 가 보겠습니다. 그 전에 와인 조금 더 드릴까요?"),
(R, "Un peu d'eau suffira. Je veux garder la tête claire.", "물이면 충분하오. 머리를 맑게 하고 싶으니까."),
(None, "Dans la cuisine, Julien parle à voix basse.", "주방에서 쥘리앵이 낮은 목소리로 말한다."),
(J, "Il veut te voir. Là, à sa table.", "널 보고 싶대. 지금 그 테이블로."),
(H, "Merde. Il va m'enfoncer devant tout le monde ?", "젠장. 모두가 보는 앞에서 날 깔아뭉개려는 거야?"),
(J, "Il parle doucement. Et il a demandé de l'eau, pas du vin. Ce n'est pas un type qui veut se battre.", "조용히 말하더라. 와인이 아니라 물을 달라고 했고. 싸우려는 사람이 아니야."),
(H, "On verra. Enlève-moi ce tablier sale, tiens. Non, laisse. Je garde mon tablier. Je suis une cuisinière, pas une mannequin.", "두고 보지. 이 더러운 앞치마 벗겨 줘... 아니, 됐어. 앞치마는 입고 갈래. 난 요리사지 모델이 아니니까."),
(None, "Hélène s'approche de la table quatre et s'arrête à un mètre du critique.", "엘렌이 4번 테이블로 다가가 비평가에게서 한 걸음쯤 떨어진 곳에 멈춘다."),
(H, "Monsieur Roux. Vous vouliez me voir ?", "루 선생님. 저를 보고 싶으셨다고요?"),
(R, "Madame Marchand. Asseyez-vous, je vous en prie. Je ne mords pas, quoi qu'on dise.", "마르샹 부인. 앉으시지요. 사람들이 뭐라 하든 나는 물지 않소."),
(H, "Je préfère rester debout. J'ai du monde en salle.", "서 있는 게 편해요. 홀에 손님이 있어서요."),
(R, "Comme vous voudrez. Alors, je vais être direct. L'œuf mayonnaise est parfait. Franche, juste, sans chichis.", "원하는 대로 하시오. 그럼 솔직히 말하겠소. 에그 마요네즈는 완벽하오. 솔직하고 정확하며 허세가 없소."),
(H, "Merci. C'est la recette de ma mère.", "감사합니다. 어머니 레시피예요."),
(R, "Je sais. J'ai mangé chez elle quand j'étais jeune critique. La mayonnaise, elle la montait à la main, au fouet.", "알고 있소. 젊은 비평가였을 때 그분의 가게에서 먹었으니. 마요네즈를 손으로 휘저어 만드셨지."),
(H, "Moi aussi. Je ne me sers jamais du mixeur.", "저도요. 믹서는 절대 안 써요."),
(R, "Bien. Passons à la blanquette. La sauce est une merveille. Onctueuse, légère, citronnée juste comme il faut.", "좋소. 블랑케트로 넘어갑시다. 소스는 경이롭소. 부드럽고 가벼우며 레몬 맛이 딱 알맞소."),
(H, "Mais ?", "하지만요?"),
(R, "Mais le veau est fibreux. Il a cuit cinq minutes de trop, peut-être dix.", "하지만 송아지 고기가 퍽퍽하오. 5분, 어쩌면 10분은 너무 익었소."),
(H, "Fibreux. Vous avez raison. La sonde m'a menti, ou c'est moi qui lui ai fait confiance.", "퍽퍽하다. 맞는 말씀이에요. 온도계가 거짓말을 했거나 제가 너무 믿은 거죠."),
(R, "Ni l'un ni l'autre. Vous avez eu peur de servir un veau cru. C'est la peur qui a cuit la viande.", "둘 다 아니오. 날고기를 낼까 봐 겁이 났던 거요. 고기를 익힌 건 두려움이오."),
(H, "C'est dur à entendre. Mais c'est juste.", "듣기 힘든 말이지만 맞는 말이네요."),
(R, "J'ai dit la même chose il y a trois ans : une cuisine qui a peur. Elle a un peu moins peur aujourd'hui, mais elle a encore peur.", "3년 전에도 같은 말을 했소. 겁먹은 요리라고. 지금은 조금 덜하지만 아직도 겁이 나 있소."),
(H, "Je n'ai pas le droit de me tromper, monsieur Roux. Ici, une erreur coûte cher.", "저는 틀릴 권리가 없어요, 루 선생님. 여기선 실수 하나가 비싸요."),
(R, "Ça, je le sais. J'ai vu la pétition sur le comptoir en entrant. Deux cent quatorze noms ?", "그건 알고 있소. 들어오면서 카운터 위 청원서를 봤소. 이름이 이백열네 개던가?"),
(H, "C'est Mme Vasseur, une cliente de trente ans de maison.", "30년 단골이신 바쉐 부인이 하셨어요."),
(R, "Une dame de caractère, j'imagine. Elle a dû signer la première.", "기개 있는 부인이겠군. 첫 번째로 서명했을 것 같소."),
(H, "Deux cent quatorze. C'est une cliente fidèle qui l'a organisée.", "이백열네 개요. 단골 한 분이 주도했어요."),
(R, "Les clients vous aiment. Moi, je ne suis pas payé pour aimer. Je suis payé pour dire ce que je goûte.", "손님들은 당신을 좋아하오. 나는 좋아하라고 돈을 받는 게 아니라 맛본 걸 말하라고 받소."),
(H, "Alors dites-moi tout. La tarte Tatin ?", "그럼 전부 말씀해 주세요. 타르트 타탱은요?"),
(R, "Je ne l'ai pas encore mangée. Je voulais d'abord vous parler du reste.", "아직 안 먹었소. 먼저 나머지에 대해 얘기하고 싶었소."),
(H, "Du reste ?", "나머지라니요?"),
(R, "De la salle, par exemple. Les murs sont fatigués. La peinture s'écaille derrière la banquette.", "예를 들어 홀 말이오. 벽이 지쳐 있소. 벤치 뒤 페인트가 벗겨졌소."),
(H, "Je sais. Je n'ai pas eu les moyens de la refaire depuis deux ans.", "알아요. 2년 동안 다시 칠할 여유가 없었어요."),
(R, "Ce n'est pas un reproche. C'est une observation. Une bonne cuisine mérite un cadre qui la sert, pas qui la trahit.", "비난이 아니라 관찰이오. 좋은 요리에는 요리를 돋보이게 하는 공간이 어울리지, 배신하는 공간은 아니오."),
(H, "Je le note.", "적어 둘게요."),
(None, "Chloé, au loin, apporte la tarte Tatin. Hélène la regarde, un peu crispée.", "멀리서 클로에가 타르트 타탱을 들고 온다. 엘렌이 약간 굳은 얼굴로 바라본다."),
(C, "Voici la tarte Tatin, monsieur. Avec la crème fraîche.", "타르트 타탱입니다, 손님. 크렘 프레슈와 함께요."),
(R, "Merci, mademoiselle. Je goûte, et je vous dis.", "고맙소, 아가씨. 먹어 보고 말해 주겠소."),
(None, "Il goûte lentement, ferme les yeux, laisse un silence qui semble durer une minute.", "그는 천천히 맛보고 눈을 감는다. 침묵이 일 분처럼 길게 느껴진다."),
(R, "La pâte est excellente, croustillante, beurrée. Les pommes sont fondantes, bien choisies.", "반죽은 훌륭하오. 바삭하고 버터 향이 나오. 사과는 부드럽고 잘 골랐소."),
(H, "Mais le caramel ?", "그런데 캐러멜은요?"),
(R, "Trop poussé. Il frôle l'amertume. Je regrette qu'il couvre le goût de la pomme.", "너무 졸였소. 쓴맛에 가깝소. 사과 맛을 덮어 버려 아쉽소."),
(H, "J'ai la main trop lourde avec le sucre brun quand je suis fatiguée.", "피곤하면 갈색 설탕을 너무 많이 넣게 돼요."),
(R, "Alors reposez-vous. Un cuisinier épuisé fait une cuisine inquiète. Et je ne parle pas du caramel.", "그럼 쉬시오. 지친 요리사는 불안한 요리를 하오. 캐러멜 얘기만이 아니오."),
(H, "Je n'ai pas le temps de me reposer, monsieur.", "쉴 시간이 없어요, 선생님."),
(R, "Je sais. Alors, laissez-moi vous dire une dernière chose, et je vous laisse retourner à vos fourneaux.", "알고 있소. 그렇다면 마지막으로 한 가지만 말하겠소. 그러고 나면 조리대로 돌아가시오."),
(H, "Je vous écoute.", "듣고 있습니다."),
(R, "Votre mère cuisinait avec ses mains et son ventre. Vous cuisinez avec votre tête, et c'est brillant.", "당신 어머니는 손과 배로 요리하셨소. 당신은 머리로 요리하고, 그건 빛나오."),
(R, "Mais il manque le ventre. Il faut que vous lâchiez un peu la bride.", "하지만 배가 빠져 있소. 고삐를 조금 늦춰야 하오."),
(H, "Lâcher la bride, quand on a quatre-vingt-douze mille euros de dettes ?", "9만 2천 유로 빚이 있는데 고삐를 늦추라고요?"),
(R, "Je ne connais pas vos dettes. Je connais votre blanquette. Elle était meilleure l'an dernier, quand vous aviez moins peur.", "당신의 빚은 모르오. 당신의 블랑케트를 알 뿐이오. 작년에는 두려움이 적어서 더 맛있었소."),
(H, "L'an dernier ? Vous êtes venu l'an dernier ?", "작년이요? 작년에도 오셨어요?"),
(R, "Deux fois. Incognito. Une fois en juin, une fois en novembre. Vous ne m'aviez pas vu.", "두 번 왔소. 몰래. 6월에 한 번, 11월에 한 번. 당신은 못 봤소."),
(H, "Pourquoi vous ne me l'avez pas dit ?", "왜 말씀하지 않으셨어요?"),
(R, "Un critique qui prévient n'est plus un critique, madame.", "미리 알리는 비평가는 더는 비평가가 아니오, 부인."),
(H, "Et l'article ? Vous allez l'écrire quand ?", "그럼 기사는요? 언제 쓰실 건가요?"),
(R, "Il paraîtra samedi prochain. Je ne sais pas encore quelle note je donnerai. Je vous le dis franchement.", "다음 주 토요일에 실릴 거요. 아직 점수를 몇 점 줄지 모르겠소. 솔직히 말하는 거요."),
(H, "Merci de votre franchise. Je ne vous demande pas d'être gentil.", "솔직하게 말씀해 주셔서 감사합니다. 친절하게 써 달라는 부탁은 안 드릴게요."),
(R, "Tant mieux. Je n'en suis pas capable. Pouvez-vous m'apporter l'addition, mademoiselle ?", "다행이오. 난 그럴 수도 없으니. 계산서 가져다주겠소, 아가씨?"),
(C, "Tout de suite, monsieur. Le café est offert par la maison.", "곧바로 가져다 드리겠습니다, 손님. 커피는 가게에서 대접합니다."),
(R, "Je vous remercie, mais non. Un critique qui accepte un café offert, c'est un critique acheté. Je paierai tout.", "고맙지만 사양하오. 공짜 커피를 받는 비평가는 매수된 비평가요. 전부 내겠소."),
(H, "Comme vous voudrez. Au revoir, monsieur Roux.", "원하시는 대로 하세요. 안녕히 가세요, 루 선생님."),
(R, "Au revoir, madame Marchand. Et pour la Tatin, goûtez avant d'envoyer. Toujours.", "안녕히 계시오, 마르샹 부인. 그리고 타탱은 내보내기 전에 꼭 맛보시오. 항상."),
(None, "Le critique sort. Hélène retourne en cuisine, pose les mains à plat sur le plan de travail. Julien et Chloé la suivent.", "비평가가 나간다. 엘렌은 주방으로 돌아와 작업대에 두 손을 짚는다. 쥘리앵과 클로에가 따라온다."),
(H, "Fibreux. Il a dit fibreux. Un veau que j'ai fait cuire quatre heures.", "퍽퍽하대. 퍽퍽하다고 했어. 내가 네 시간 익힌 송아지를."),
(J, "Il a dit aussi que la sauce était une merveille. Et que l'œuf était parfait.", "소스는 경이롭다고도 했어. 달걀 요리는 완벽하다고도 했고."),
(H, "Et que je cuisinais avec ma tête, pas avec mon ventre. Qu'est-ce qu'il en sait, lui ?", "머리로 요리하지 배로는 안 한다고도 했지. 그 사람이 뭘 안다고."),
(C, "Moi, je crois qu'il a raison pour la peur. Pardon, Hélène.", "저는 두려움 얘기는 맞는 것 같아요. 죄송해요, 엘렌."),
(H, "Toi aussi, tu t'y mets ? Merde, il a raison. C'est ça qui m'énerve.", "너까지 그러니? 젠장, 그 사람 말이 맞아. 그게 화나는 거야."),
(J, "Hélène, un critique qui vient trois fois en un an sans le dire, c'est qu'il s'intéresse à toi.", "엘렌, 1년에 세 번이나 말없이 온 비평가라면 널 눈여겨본다는 거야."),
(H, "Ou qu'il cherche une bonne chute pour son article. « Le restaurant qui meurt par peur. »", "아니면 기사를 마무리할 좋은 문장을 찾는 거겠지. « 두려움 때문에 죽어 가는 식당 »."),
(J, "Ne dis pas ça. Dis plutôt « le restaurant qui peut mieux faire ».", "그런 말 하지 마. 차라리 « 더 잘할 수 있는 식당 »이라고 해."),
(H, "C'est pareil, avec un point d'exclamation en moins.", "느낌표 하나만 빠졌지 같은 말이야."),
(C, "Je note dans mon carnet : « fibreux », « onctueux », « croustillant », « fondant ». Ça fait quatre mots.", "수첩에 적었어요. « 퍽퍽한 », « 부드러운 », « 바삭한 », « 녹아내리는 ». 네 단어예요."),
(H, "Ajoute « amer ». Et « lâcher la bride ». Ça, c'est une expression.", "« 쓴 »도 적어. 그리고 « 고삐를 늦추다 ». 그건 관용구야."),
(C, "Compris. Je mets aussi « rester debout ». Ça, c'était vous.", "알겠어요. « 서 있다 »도 적을게요. 그건 엘렌이 한 말이에요."),
(H, "Très drôle. Allez, au travail. Il reste huit couverts et la sonde à régler.", "아주 웃기네. 자, 일하자. 아직 여덟 명이 남았고 온도계도 조정해야 해."),
(J, "Tu veux que je baisse la température de la blanquette pour ce soir ?", "오늘 저녁 블랑케트는 온도를 낮출까?"),
(H, "Soixante-cinq, pas soixante-huit. Je la sortirai plus tôt. Et cette fois, je goûterai le veau avant d'envoyer.", "68도 말고 65도로. 더 일찍 꺼낼 거야. 이번엔 송아지를 먼저 맛볼 거고."),
(C, "Et s'il revient une quatrième fois ? Il goûtera quoi ?", "네 번째로 또 오면요? 무엇을 맛볼까요?"),
(H, "Une blanquette moins peureuse. Et une Tatin qui sent la pomme.", "덜 겁먹은 블랑케트와 사과 향이 나는 타탱이겠지."),
(J, "Et pour la Tatin ?", "타탱은?"),
(H, "Moins de sucre brun. Je la refais ce soir, après le service. Même si je dois y passer la nuit.", "갈색 설탕은 줄일 거야. 오늘 저녁 서비스 끝나고 다시 만들 거야. 밤을 새우더라도."),
(J, "Pas toute seule. Je reste, et je goûterai avec toi.", "혼자는 안 돼. 내가 남아서 같이 맛볼게."),
(None, "Elle reprend sa spatule. Dehors, le ciel de la rue Saint-Maur s'éclaircit.", "그녀가 주걱을 다시 든다. 밖으로 생모르 거리의 하늘이 갠다."),
]

